from pathlib import Path
import json
P=Path(__file__).parent
THEMES=[
 dict(id='blue',name='晴空蓝',en='SKY / CLEAR',desc='清爽、利落。白底与蓝色操作，头像像轻巧的圆角贴纸。',primary='#315BD6',ink='#202D48',muted='#58667F',bg='#F5F7FD',soft='#E8EEFC',border='#D7E0F3',accent='#96BBFF',fur='#F7FAFF',shade='#CDDDF6',dark='#151D30',darkmuted='#AFBCD8',light='#E8EEFF',focus='#2B3F6C'),
 dict(id='violet',name='雾紫',en='IRIS / SOFT',desc='柔和、安静。低饱和紫与雾白，动物采用更柔软的轮廓。',primary='#7054B3',ink='#342B45',muted='#706478',bg='#FAF8FC',soft='#EEE7F6',border='#DFD6EB',accent='#C9B5EE',fur='#FBF8FF',shade='#DCCEEF',dark='#241D30',darkmuted='#C2B3D2',light='#F2EAFB',focus='#4C385F'),
 dict(id='clay',name='杏陶',en='APRICOT / WARM',desc='温暖、亲近。杏色和陶土色，动物像一组简洁的纸片玩偶。',primary='#A64B32',ink='#493329',muted='#7B675C',bg='#FCF8F3',soft='#F4E6DA',border='#E9D8C8',accent='#E9B785',fur='#FFF7E9',shade='#E8C8A9',dark='#2A211C',darkmuted='#D0BBA9',light='#FFF0E1',focus='#594032'),
 dict(id='graphite',name='石墨黄',en='GRAPHITE / PLAY',desc='克制、有辨识度。黑白界面，只用一点纸黄色点亮图标和头像。',primary='#34373E',ink='#272A30',muted='#64676C',bg='#F7F7F5',soft='#ECECE8',border='#DCDDD7',accent='#F2D16B',fur='#FAF9F2',shade='#E5D493',dark='#1C1D20',darkmuted='#BABCC1',light='#F3F3EC',focus='#464334')]
animals=[('cat','小猫'),('rabbit','小兔'),('dog','小狗'),('sheep','绵羊'),('monkey','小猴'),('chick','小鸡'),('lizard','小蜥蜴'),('alpaca','羊驼'),('otter','水獭'),('capybara','卡皮巴拉')]
def animal(kind,t):
 f=t['fur']; sh=t['shade']; ink=t['ink']; col=t['primary']; ac=t['accent']
 outline=ink if t['id']=='graphite' else col
 stroke=2.4 if t['id']=='graphite' else 1.7
 heads={
 'cat':f'<path d="M20 51V22l13 10q15-8 30 0l13-10v29q0 23-28 23T20 51Z"/> <path d="m25 31 7 7-7 2m46-9-7 7 7 2" fill="{sh}" stroke="none"/>',
 'rabbit':f'<ellipse cx="34" cy="24" rx="8" ry="20"/><ellipse cx="62" cy="24" rx="8" ry="20"/><rect x="20" y="31" width="56" height="43" rx="22"/><path d="M34 13v16m28-16v16" stroke="{sh}" stroke-width="6"/>',
 'dog':f'<path d="M25 30Q8 23 13 54q3 9 14-1m44-23q17-7 12 24-3 9-14-1" fill="{sh}"/><rect x="23" y="28" width="50" height="46" rx="20"/><ellipse cx="48" cy="59" rx="17" ry="11" fill="{sh}" stroke="none"/>',
 'sheep':f'<path d="M23 66Q9 61 17 48q-9-14 4-19-3-14 12-12 11-12 21-2 17-4 19 12 16 5 7 20 10 16-7 21Z"/><rect x="28" y="32" width="40" height="39" rx="18" fill="{sh}" stroke="none"/>',
 'monkey':f'<circle cx="18" cy="46" r="12" fill="{sh}"/><circle cx="78" cy="46" r="12" fill="{sh}"/><rect x="22" y="23" width="52" height="51" rx="24" fill="{sh}"/><path d="M48 40C24 16 17 69 48 71 79 69 72 16 48 40Z" stroke="none"/>',
 'chick':f'<path d="M40 26q-12-16 1-13l6 9q-1-24 10-14l-2 16q17-12 13 2" fill="{ac}"/><rect x="20" y="28" width="56" height="46" rx="22"/><path d="m42 55 6-4 6 4-6 6Z" fill="{col}" stroke="none"/>',
 'lizard':f'<path d="m32 32-7-16 16 10 12-14 8 18" fill="{sh}"/><path d="M19 49q0-24 29-22 29 0 29 22v8q0 18-29 18T19 57Z"/><circle cx="35" cy="43" r="10" fill="{sh}" stroke="none"/><circle cx="61" cy="43" r="10" fill="{sh}" stroke="none"/>',
 'alpaca':f'<path d="M27 36 22 10q10-8 17 20m19 0q7-28 17-20l-5 29"/><rect x="23" y="29" width="50" height="45" rx="19"/><ellipse cx="48" cy="59" rx="16" ry="10" fill="{sh}" stroke="none"/>',
 'otter':f'<circle cx="26" cy="29" r="8" fill="{sh}"/><circle cx="70" cy="29" r="8" fill="{sh}"/><rect x="20" y="27" width="56" height="47" rx="23" fill="{sh}"/><ellipse cx="48" cy="58" rx="23" ry="15" stroke="none"/>',
 'capybara':f'<circle cx="28" cy="27" r="8"/><circle cx="68" cy="27" r="8"/><rect x="20" y="27" width="56" height="47" rx="19" fill="{sh}"/><rect x="30" y="47" width="48" height="23" rx="10" stroke="none"/>'}
 eyeY=44 if kind=='lizard' else 47
 eyes=f'<path d="M35 {eyeY}v3m26-3v3" stroke="{ink}" stroke-width="3.5" stroke-linecap="round"/>'
 mouth='' if kind=='chick' else f'<path d="m44 57 4 3 4-3" fill="none" stroke="{ink}" stroke-width="1.8" stroke-linecap="round"/>'
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96" role="img" aria-label="{dict(animals)[kind]}"><g fill="{f}" stroke="{outline}" stroke-width="{stroke}" stroke-linejoin="round">{heads[kind]}</g>{eyes}{mouth}<rect x="27" y="70" width="42" height="22" rx="7" fill="{col}"/><path d="m33 76 15 9 15-9" stroke="{ac}" stroke-width="2" fill="none"/><circle cx="27" cy="76" r="6" fill="{f}" stroke="{outline}" stroke-width="{stroke}"/><circle cx="69" cy="76" r="6" fill="{f}" stroke="{outline}" stroke-width="{stroke}"/></svg>'
def app(t):
 c=t['primary']; a=t['accent']; w='#FFFFFF'
 shapes={
 'blue':f'<rect x="30" y="32" width="44" height="48" rx="12" fill="{a}"/><rect x="54" y="50" width="44" height="48" rx="12" fill="{w}"/><path d="M43 52h27m-9-9 10 9-10 9" fill="none" stroke="{c}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>',
 'violet':f'<path d="M31 40h33a18 18 0 0 1 0 36H44" fill="none" stroke="{w}" stroke-width="16" stroke-linecap="round"/><path d="M97 88H64a18 18 0 0 1 0-36h20" fill="none" stroke="{a}" stroke-width="16" stroke-linecap="round"/>',
 'clay':f'<path d="m28 46 36-18 36 18v40L64 104 28 86Z" fill="{w}"/><path d="m28 46 36 18 36-18M64 64v40" fill="none" stroke="{c}" stroke-width="5"/><path d="m47 38 35 18v15" fill="none" stroke="{a}" stroke-width="8" stroke-linejoin="round"/>',
 'graphite':f'<rect x="31" y="31" width="66" height="66" rx="18" fill="{a}"/><path d="M45 48h36v33M47 79l32-29" stroke="{c}" stroke-width="9" stroke-linejoin="round" stroke-linecap="round" fill="none"/>'}
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img" aria-label="拾传 {t["name"]} App 图标"><rect width="128" height="128" rx="29" fill="{c}"/>{shapes[t["id"]]}</svg>'
def contrast(a,b):
 def L(s):
  rgb=[int(s[i:i+2],16)/255 for i in [1,3,5]];return sum((x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4)*w for x,w in zip(rgb,[.2126,.7152,.0722]))
 lo,hi=sorted([L(a),L(b)]);return round((hi+.05)/(lo+.05),2)
for t in THEMES:
 d=P/t['id'];d.mkdir(exist_ok=True)
 for key,name in animals:(d/(key+'.svg')).write_text(animal(key,t))
 (d/'app-icon.svg').write_text(app(t))
 t['contrast']={'body':contrast(t['ink'],t['bg']),'secondary':contrast(t['muted'],t['bg']),'button':contrast('#FFFFFF',t['primary'])}
 (d/'tokens.json').write_text(json.dumps(t,ensure_ascii=False,indent=2))
(P/'themes.json').write_text(json.dumps(THEMES,ensure_ascii=False,indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#F1F1EF;color:#26272B;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}button,a{font:inherit}a{color:inherit}button{cursor:pointer}header{max-width:1440px;margin:auto;padding:56px 40px 32px}h1{font-size:44px;letter-spacing:-2px;margin:14px 0}header p{color:#606269;line-height:1.8;max-width:700px}.eyebrow{font:12px monospace;letter-spacing:2px}nav{position:sticky;top:0;z-index:5;background:#f1f1eff2;backdrop-filter:blur(16px);padding:14px 40px;display:flex;gap:10px;border-bottom:1px solid #d8d8d5}nav button{padding:10px 18px;min-height:44px;border:1px solid #ccc;border-radius:30px;background:transparent}nav button[aria-pressed=true]{background:#292B30;color:white;border-color:#292B30}.direction{padding:36px 40px 56px;border-bottom:1px solid #d8d8d5;scroll-margin-top:85px}.section-head{display:flex;align-items:center;gap:24px;max-width:1440px;margin:0 auto 28px}.app-large{width:88px;height:88px}.section-head h2{font-size:32px;margin:6px 0}.section-head p{margin:0;color:#61636b;font-size:14px}.preview-link{margin-left:auto;text-decoration:none;border-radius:12px;padding:14px 20px;background:var(--primary);color:white;font-weight:600}.samples{max-width:1440px;margin:auto;display:flex;align-items:flex-start;gap:28px;flex-wrap:wrap}.phone,.desktop{background:var(--bg);color:var(--ink);border:1px solid var(--border);border-radius:22px;overflow:hidden;box-shadow:0 12px 32px #00000008}.desktop{width:380px;height:550px;display:flex;flex-direction:column}.phone{width:310px;height:620px;display:flex;flex-direction:column}.bar{padding:18px 20px;display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--border)}.bar img{width:40px;height:40px}.grow{flex:1}.muted{font-size:12px;color:var(--muted);line-height:1.6}.title{font-weight:650;font-size:17px}.dots{font-size:22px;color:var(--muted)}.body{padding:20px;flex:1}.meta{font-size:12px;color:var(--muted);margin-bottom:10px}.file{background:white;border:1px solid var(--border);border-radius:13px;padding:14px;margin-bottom:20px;display:flex;align-items:center;gap:12px}.filetype{width:38px;height:44px;background:var(--soft);color:var(--primary);font-size:10px;font-weight:700;display:grid;place-items:center;border-radius:8px;flex-shrink:0}.file b{font-size:14px}.actions{font-size:12px;color:var(--primary);padding-top:8px}.bubble{padding:12px 15px;background:var(--soft);border-radius:4px 14px 14px;display:inline-block;font-size:14px;margin-bottom:28px}.outgoing{background:var(--primary);color:white;border-radius:14px 4px 14px 14px;padding:12px 14px;max-width:240px;margin-left:auto;font-size:14px}.progress{height:4px;border-radius:4px;background:var(--border);margin-top:10px}.progress i{display:block;width:68%;height:100%;background:var(--primary);border-radius:4px}.composer{display:flex;align-items:center;gap:12px;padding:14px 16px;border-top:1px solid var(--border);font-size:13px;color:var(--muted)}.send{width:34px;height:34px;border-radius:10px;background:var(--primary);color:white;display:grid;place-items:center;font-size:20px}.status{padding:15px 23px 7px;display:flex;justify-content:space-between;font-size:12px}.assets{flex:1;min-width:280px;max-width:530px}.asset-panel{background:#ffffff88;border:1px solid #ddddda;border-radius:20px;padding:24px;margin-bottom:20px}.asset-panel h3{font-size:14px;margin:0 0 22px}.swatches{display:flex;gap:8px;flex-wrap:wrap}.swatch{flex:1;min-width:58px}.swatch i{display:block;height:36px;border-radius:8px;border:1px solid #00000008}.swatch span{font:10px monospace;display:block;padding-top:7px;color:#62656C}.animals{display:grid;grid-template-columns:repeat(5,1fr);gap:18px 10px}.animals figure{margin:0;text-align:center}.animals img{width:54px;height:54px;background:var(--soft);border-radius:16px;padding:3px}.animals figcaption{font-size:11px;color:#62656C;margin-top:6px}.app-sizes{display:flex;align-items:flex-end;gap:16px}.terminal{background:var(--dark);color:var(--light);font:12px/1.8 monospace;border-radius:14px;padding:20px;margin-top:20px}.terminal .dim{color:var(--darkmuted)}.terminal .sel{background:var(--focus);color:var(--accent);padding:5px 8px;margin:12px -8px}.asset-panel a{font-size:12px;text-decoration:none;border-bottom:1px solid #aaa}.foot{max-width:1440px;margin:auto;padding:32px 40px;color:#666;font-size:13px;line-height:1.9}[hidden]{display:none!important}a:focus-visible,button:focus-visible{outline:3px solid #315BD6;outline-offset:4px}@media(max-width:750px){header{padding:28px 20px}h1{font-size:32px}nav{padding:10px 16px;overflow:auto}nav button{white-space:nowrap}.direction{padding:28px 16px}.section-head{flex-wrap:wrap;gap:16px}.preview-link{margin-left:0}.samples{gap:20px}.desktop,.phone{width:100%;max-width:390px}.assets{max-width:390px}.section-head h2{font-size:26px}.section-head p{line-height:1.7}.app-large{width:64px;height:64px}}'''
sections=[]
for i,t in enumerate(THEMES):
 tid=t['id']; styles=';'.join('--'+k+':'+t[k] for k in ['primary','ink','muted','bg','soft','border','accent','dark','darkmuted','light','focus'])
 def file():return '<div class="file"><span class="filetype">PDF</span><div class="grow"><b>品牌视觉规范.pdf</b><div class="muted">24.8 MB · 已接收</div><div class="actions">打开　另存为</div></div></div>'
 def bar():return f'<div class="bar"><img src="{tid}/cat.svg" alt="小猫群头像"><div class="grow"><div class="title">设计协作</div><div class="muted">3 台设备在线</div></div><span class="dots">···</span></div>'
 def composer():return '<div class="composer"><span style="font-size:23px">＋</span><span class="grow">发消息或文件…</span><span class="send">↑</span></div>'
 desktop=f'<div class="desktop">{bar()}<div class="body"><div class="meta">林同学 · 10:24</div>{file()}<div class="bubble">这版已经整理好，可以直接用了。</div><div class="meta" style="text-align:right">我 · 10:28</div><div class="file" style="background:var(--soft)"><span class="filetype">ZIP</span><div class="grow"><b>发布物料.zip</b><div class="muted">正在发送 · 68%</div><div class="progress"><i></i></div></div></div></div>{composer()}</div>'
 phone=f'<div class="phone"><div class="status"><b>9:41</b><span>Wi-Fi　100%</span></div>{bar()}<div class="body"><div class="meta">林同学 · 10:24</div><div class="bubble">资料放这里了。</div>{file()}<div class="outgoing">收到，我把参考图也发过来。</div></div>{composer()}<div style="height:20px"></div></div>'
 sw=''.join(f'<div class="swatch"><i style="background:{t[k]}"></i><span>{t[k]}</span></div>' for k in ['primary','accent','bg','ink','soft'])
 av=''.join(f'<figure><a href="{tid}/{key}.svg" download><img src="{tid}/{key}.svg" alt="{name}"></a><figcaption>{name}</figcaption></figure>' for key,name in animals)
 assets=f'<div class="assets"><div class="asset-panel"><h3>配色 / COLOR</h3><div class="swatches">{sw}</div></div><div class="asset-panel"><h3>群头像 / 10 ANIMALS</h3><div class="animals">{av}</div></div><div class="asset-panel"><h3>App 图标 / 96 · 48 · 24 px</h3><div class="app-sizes"><img src="{tid}/app-icon.svg" width="96" height="96" alt="App图标"><img src="{tid}/app-icon.svg" width="48" height="48" alt="48像素图标"><img src="{tid}/app-icon.svg" width="24" height="24" alt="24像素图标"><a href="{tid}/app-icon.svg" download>下载 SVG</a></div></div><div class="terminal">拾传 / 设计协作 <span class="dim">· 3 在线</span><div class="sel">› 品牌资料.zip　下载中 68%</div><div class="dim">Enter 操作　Ctrl+O 发文件</div></div></div>'
 sections.append(f'<section class="direction" id="{tid}" style="{styles}"><div class="section-head"><img class="app-large" src="{tid}/app-icon.svg" alt="{t["name"]}App图标"><div><div class="eyebrow">0{i+1} / {t["en"]}</div><h2>{t["name"]}</h2><p>{t["desc"]}</p></div><a class="preview-link" href="{tid}/preview.html">预览整套界面 ↗</a></div><div class="samples">{desktop}{phone}{assets}</div></section>')
nav='<button data-filter="all" aria-pressed="true">全部对比</button>'+''.join(f'<button data-filter="{t["id"]}" aria-pressed="false">{t["name"]}</button>' for t in THEMES)
html=f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>拾传 · 四套配色与图标</title><style>{css}</style><header><div class="eyebrow">PICKDROP / COLOR & IDENTITY / 2026.10.11</div><h1>换一种颜色，也换一种性格。</h1><p>四套完整配色，同一套精简小窗。每套包含重新绘制的动物群头像与 App 图标，可继续查看全部 17 个界面。</p></header><nav>{nav}</nav>'+''.join(sections)+'<div class="foot">图标为可编辑 SVG，点击动物头像可下载。配色与图标均为候选设计，未替换正式应用资产。<br>正文、辅助文字及按钮文字均已检查对比度；详细色值见各方案 tokens.json。</div><script>document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-filter]").forEach(x=>x.setAttribute("aria-pressed",x===b));document.querySelectorAll(".direction").forEach(s=>s.hidden=b.dataset.filter!=="all"&&s.id!==b.dataset.filter);});</script></html>'
(P/'index.html').write_text(html)
print(json.dumps({t['name']:t['contrast'] for t in THEMES},ensure_ascii=False))
